int fm10k_init_module(void)
{
    int err;

    /* Log driver version and copyright information */
    printk(KERN_INFO "FM10K: Driver Version %s\n", FM10K_DRIVER_VERSION);
    printk(KERN_INFO "FM10K: Copyright (c) 2009-2015 Intel Corporation\n");

    /* Create workqueue for the driver */
    fm10k_wq = create_singlethread_workqueue("fm10k_wq");
    if (!fm10k_wq)
        return -ENOMEM;

    /* Initialize debugging support */
    fm10k_dbg_init();

    /* Register the PCI driver */
    err = pci_register_driver(&fm10k_driver);
    if (err) {
        destroy_workqueue(fm10k_wq);
        fm10k_dbg_exit();
    }

    return err;
}

int fm10k_init_module(void)
{
    int err;

    /* Log driver version and copyright information */
    pr_info("FM10K driver initialized\n");

    /* Create workqueue for the driver */
    fm10k_wq = create_singlethread_workqueue("fm10k_wq");
    if (!fm10k_wq)
        return -ENOMEM;

    /* Initialize debugging */
    fm10k_debug_init();

    /* Register the PCI driver */
    err = pci_register_driver(&fm10k_pci_driver);
    if (err)
        destroy_workqueue(fm10k_wq);

