int fm10k_init_module(void)
{
    int err;

    pr_info("FM10K driver version 1.0 initialized\n");
    pr_info("Copyright (c) 2023 Intel Corporation\n");

    fm10k_debug_init();
    err = fm10k_workqueue_create();
    if (err) {
        pr_err("Failed to create workqueue\n");
        return err;
    }

    err = pci_register_driver(&fm10k_pci_driver);
    if (err) {
        pr_err("Failed to register PCI driver\n");
        fm10k_workqueue_destroy();
    }

    return err;
}
